mapper.select:
SELECT s.jccjsj AS time,s.jcz AS raw_value,NULL::float8 AS value
FROM dwd_ql_jc_jcz_inc s
WHERE s.sscsdm=#{city} AND s.dwbsm=#{point} AND s.sbbsm=#{device}
AND s.jczb IS NOT DISTINCT FROM #{metric}
AND s.jccjsj BETWEEN #{from} AND #{to} AND coalesce(s.sjtbzt,'') != 'D'
ORDER BY s.jccjsj,s.bsm LIMIT 2001

WITH selected_points(point_id,device_id,metric) AS ( VALUES
(#{p.pointId}::text,#{p.deviceId}::text,#{p.metric}::text)
), threshold_latest AS ( SELECT DISTINCT ON(sscsdm,bsm) * FROM dwd_ql_jc_jcxyz_inc t WHERE sscsdm=#{city} AND nullif(trim(bsm),'') IS NOT NULL ORDER BY sscsdm,bsm,sjtbsj DESC NULLS LAST,(sjtbzt='D') DESC NULLS LAST,to_jsonb(t)::text DESC ) SELECT t.bsm AS id,p.point_id,p.device_id,t.jczb AS metric,t.sblx AS device_type,t.jcjb AS level, t.yzsx AS upper,t.yzxx AS lower,t.bjyz AS legacy_threshold,t.bz AS note,t.sjtbsj AS source_updated_at FROM threshold_latest t JOIN selected_points p ON t.sbbsm=p.device_id AND t.jczb IS NOT DISTINCT FROM p.metric WHERE coalesce(t.sjtbzt,'')!='D' ORDER BY p.point_id,p.device_id,t.jczb,t.jcjb,t.yzxx,t.yzsx,t.bsm


SELECT DISTINCT p.sscsdm AS city,p.bridge_id AS bridge
FROM point_bridge p JOIN device_source d ON d.dwbsm=p.bsm AND d.sscsdm=p.sscsdm
WHERE p.bsm=#{point} AND d.bsm=#{device} AND d.jczb=#{metric}
